def on_line_segment(r1, c1, r2, c2, r, c):
    """Check if (r,c) lies on line segment from (r1,c1) to (r2,c2)"""
    dr1, dc1 = r2 - r1, c2 - c1

    # Check if point is collinear
    if not ((r == r1 + t * dr1 and c == c1 + t * dc1) for t in [0.5]):  # placeholder

