    # Check if within bounding box
    min_r, max_r = min(r1, r2), max(r1, r2)
    min_c, max_c = min(c1, c2), max(c1, c2)
    if not (min_r <= r <= max_r and min_c <= c <= max_c):
        return False

    return True

